using System.Numerics;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public enum TransformMode { Move, Rotate, Scale }
public sealed class EditorSession { public ShellProject Project {get;private set;}=new(); public SceneObject? Selected {get;private set;} public TransformMode Mode {get;set;}=TransformMode.Move; public event Action? Changed; public void NewProject(string name){Project=new(){Name=name};Selected=null;Changed?.Invoke();} public void Add(SceneObject o){Project.Objects.Add(o);Selected=o;Changed?.Invoke();} public void Select(Guid id){Selected=Project.Objects.FirstOrDefault(x=>x.Id==id);Changed?.Invoke();} public void DeleteSelected(){if(Selected==null)return;Project.Objects.Remove(Selected);Selected=null;Changed?.Invoke();} public SceneObject? DuplicateSelected(){if(Selected==null)return null;var c=new SceneObject{Name=Selected.Name+" Copy",Type=Selected.Type,Position=Selected.Position+new Vector3(.25f,.25f,0),Rotation=Selected.Rotation,Scale=Selected.Scale,MaterialId=Selected.MaterialId,Collision=Selected.Collision,FloorLevel=Selected.FloorLevel};Add(c);return c;} }
